BEGIN;
CREATE SCHEMA IF NOT EXISTS auth_admin_hml;
REVOKE ALL ON SCHEMA auth_admin_hml FROM PUBLIC;
CREATE TABLE IF NOT EXISTS auth_admin_hml."user"(id text PRIMARY KEY,"name" text NOT NULL,"email" text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,"image" text,"createdAt" timestamptz NOT NULL,"updatedAt" timestamptz NOT NULL,"twoFactorEnabled" boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS auth_admin_hml."session"(id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,"token" text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL,"updatedAt" timestamptz NOT NULL,"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES auth_admin_hml."user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "session_userId_idx" ON auth_admin_hml."session"("userId");
CREATE TABLE IF NOT EXISTS auth_admin_hml."account"(id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES auth_admin_hml."user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,"scope" text,"password" text,"createdAt" timestamptz NOT NULL,"updatedAt" timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS "account_userId_idx" ON auth_admin_hml."account"("userId");
CREATE TABLE IF NOT EXISTS auth_admin_hml."verification"(id text PRIMARY KEY,"identifier" text NOT NULL,"value" text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL,"updatedAt" timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS "verification_identifier_idx" ON auth_admin_hml."verification"("identifier");
CREATE TABLE IF NOT EXISTS auth_admin_hml."twoFactor"(id text PRIMARY KEY,"secret" text NOT NULL,"backupCodes" text NOT NULL,"userId" text NOT NULL REFERENCES auth_admin_hml."user"(id) ON DELETE CASCADE,"verified" boolean DEFAULT true,"failedVerificationCount" integer DEFAULT 0,"lockedUntil" timestamptz);
CREATE INDEX IF NOT EXISTS "twoFactor_secret_idx" ON auth_admin_hml."twoFactor"("secret");
CREATE INDEX IF NOT EXISTS "twoFactor_userId_idx" ON auth_admin_hml."twoFactor"("userId");
CREATE TABLE IF NOT EXISTS auth_admin_hml."rateLimit"(id text PRIMARY KEY,"key" text NOT NULL UNIQUE,"count" integer NOT NULL,"lastRequest" bigint NOT NULL);
CREATE TABLE IF NOT EXISTS auth_admin_hml.instalacao(id integer PRIMARY KEY CHECK(id=1),consumida boolean NOT NULL DEFAULT false);
INSERT INTO auth_admin_hml.instalacao(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS auth_admin_hml.mfa_sessoes(sessao_id text PRIMARY KEY REFERENCES auth_admin_hml.session(id) ON DELETE CASCADE,usuario_id text NOT NULL,confirmado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_admin_hml.limites(chave text PRIMARY KEY,quantidade integer NOT NULL,inicio timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS auth_admin_hml.pedidos(id uuid PRIMARY KEY,protocolo text UNIQUE NOT NULL CHECK(protocolo LIKE 'HML-%'),chave_hash text NOT NULL,versao integer NOT NULL DEFAULT 1,aprovado_por text,aprovado_em timestamptz,desafio_id uuid,codigo_hash text,expira_em timestamptz,tentativas integer NOT NULL DEFAULT 0,confirmado_em timestamptz,consumido_em timestamptz);
CREATE TABLE IF NOT EXISTS auth_admin_hml.auditoria(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,evento text NOT NULL,usuario_id text,pedido_id uuid,criado_em timestamptz NOT NULL DEFAULT now());
COMMIT;
